<template>
  <section class="mx-auto max-w-3xl space-y-6"><header><NuxtLink to="/admin/education" class="text-sm font-semibold text-[var(--accent-hover)] hover:underline focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--border-focus)]">← Back to education</NuxtLink><div class="mt-3 flex flex-wrap items-center justify-between gap-3"><h1 class="text-3xl font-bold">{{ isNew ? 'Add education' : 'Edit education' }}</h1><span v-if="isDirty" class="text-sm font-semibold text-[var(--accent-hover)]">Unsaved changes</span></div></header>
    <div v-if="loadPending" class="space-y-4" aria-busy="true" aria-label="Loading education"><div v-for="n in 5" :key="n" class="h-12 animate-pulse rounded-md bg-[var(--background-muted)]" /></div><div v-else-if="loadError" class="rounded-lg border border-red-700/30 bg-[var(--background-card)] p-6" role="alert"><h2 class="font-semibold">Education entry could not be loaded</h2><NuxtLink to="/admin/education" class="mt-4 inline-flex min-h-11 items-center rounded-md border border-[var(--border-subtle)] px-4 text-sm font-semibold focus-visible:ring-2 focus-visible:ring-[var(--border-focus)]">Back to education</NuxtLink></div>
    <form v-else class="space-y-6 rounded-lg border border-[var(--border-subtle)] bg-[var(--background-card)] p-4 shadow-[var(--shadow-sm)] sm:p-6" novalidate @submit.prevent="save"><div class="grid gap-5 sm:grid-cols-2"><div class="sm:col-span-2"><label for="institution" class="mb-2 block text-sm font-semibold">Institution</label><input id="institution" v-model="form.institution" name="institution" autocomplete="organization" maxlength="200" :aria-invalid="Boolean(errors.institution)" class="w-full rounded-md border border-[var(--border-subtle)] bg-[var(--background-page)] px-3 py-3 focus:border-[var(--border-focus)] focus:outline-none" /><p v-if="errors.institution" class="mt-2 text-sm text-red-800" role="alert">{{ errors.institution }}</p></div><div class="sm:col-span-2"><label for="degree" class="mb-2 block text-sm font-semibold">Degree or program</label><input id="degree" v-model="form.degree" name="degree" autocomplete="off" maxlength="200" :aria-invalid="Boolean(errors.degree)" class="w-full rounded-md border border-[var(--border-subtle)] bg-[var(--background-page)] px-3 py-3 focus:border-[var(--border-focus)] focus:outline-none" /><p v-if="errors.degree" class="mt-2 text-sm text-red-800" role="alert">{{ errors.degree }}</p></div><div><label for="start-date" class="mb-2 block text-sm font-semibold">Start date <span class="font-normal text-[var(--foreground-muted)]">(optional)</span></label><input id="start-date" v-model="form.start_date" name="start_date" type="date" class="w-full rounded-md border border-[var(--border-subtle)] bg-[var(--background-page)] px-3 py-3 focus:border-[var(--border-focus)] focus:outline-none" /></div><div><label for="end-date" class="mb-2 block text-sm font-semibold">End date <span class="font-normal text-[var(--foreground-muted)]">(optional)</span></label><input id="end-date" v-model="form.end_date" name="end_date" type="date" class="w-full rounded-md border border-[var(--border-subtle)] bg-[var(--background-page)] px-3 py-3 focus:border-[var(--border-focus)] focus:outline-none" /><p v-if="errors.end_date" class="mt-2 text-sm text-red-800" role="alert">{{ errors.end_date }}</p></div><div><label for="sort-order" class="mb-2 block text-sm font-semibold">Sort order</label><input id="sort-order" v-model.number="form.sort_order" name="sort_order" type="number" min="0" max="100000" inputmode="numeric" class="w-full rounded-md border border-[var(--border-subtle)] bg-[var(--background-page)] px-3 py-3 focus:border-[var(--border-focus)] focus:outline-none" /></div></div><div class="flex flex-col gap-4 border-t border-[var(--border-subtle)] pt-5 sm:flex-row sm:justify-between"><label class="flex min-h-11 items-center gap-3 text-sm font-semibold"><input v-model="form.is_expected" name="is_expected" type="checkbox" class="h-5 w-5 rounded border-[var(--border-subtle)] text-[var(--accent-primary)] focus:ring-2 focus:ring-[var(--border-focus)]" /> Still in progress / expected</label><label class="flex min-h-11 items-center gap-3 text-sm font-semibold"><input v-model="form.is_published" name="is_published" type="checkbox" class="h-5 w-5 rounded border-[var(--border-subtle)] text-[var(--accent-primary)] focus:ring-2 focus:ring-[var(--border-focus)]" /> Publish on portfolio</label></div><div v-if="formError" class="rounded-md border border-red-700/30 bg-red-50 px-4 py-3 text-sm text-red-900" role="alert">{{ formError }}</div><div v-if="successMessage" class="rounded-md border border-emerald-700/30 bg-emerald-50 px-4 py-3 text-sm text-emerald-900" role="status" aria-live="polite">{{ successMessage }}</div><div class="flex flex-col-reverse gap-3 sm:flex-row"><button type="submit" class="min-h-11 rounded-md bg-[var(--accent-primary)] px-5 text-sm font-semibold text-white hover:bg-[var(--accent-hover)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--border-focus)] disabled:opacity-60" :disabled="saving" :aria-busy="saving">{{ saving ? 'Saving…' : 'Save education' }}</button><NuxtLink to="/admin/education" class="inline-flex min-h-11 items-center justify-center rounded-md border border-[var(--border-subtle)] px-5 text-sm font-semibold focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--border-focus)]">Cancel</NuxtLink></div></form>
  </section>
</template>
<script setup lang="ts">
import { z } from 'zod'
definePageMeta({ layout: 'admin', middleware: ['auth'] })
const route = useRoute(); const id = computed(() => String(route.params.id)); const isNew = computed(() => id.value === 'new')
const schema = z.object({ institution: z.string().trim().min(1, 'Institution is required.').max(200), degree: z.string().trim().min(1, 'Degree or program is required.').max(200), start_date: z.string().date().nullable(), end_date: z.string().date().nullable(), is_expected: z.boolean(), sort_order: z.number().int().min(0).max(100000), is_published: z.boolean() }).strict().refine((value) => !value.start_date || !value.end_date || value.end_date >= value.start_date, { path: ['end_date'], message: 'End date must not precede start date.' })
type Form = z.infer<typeof schema>; interface Response extends Form { id: string }
const form = ref<Form>({ institution: '', degree: '', start_date: null, end_date: null, is_expected: false, sort_order: 0, is_published: true }); const loadPending = ref(!isNew.value); const loadError = ref<unknown>(null); const saving = ref(false); const formError = ref(''); const successMessage = ref(''); const errors = ref<Record<string, string>>({}); const initialSnapshot = ref(''); const ignoreLeavePrompt = ref(false)
if (!isNew.value) { const { data, pending, error } = await useFetch<Response>(`/api/admin/education/${id.value}`); loadPending.value = pending.value; loadError.value = error.value; if (data.value) form.value = { institution: data.value.institution, degree: data.value.degree, start_date: data.value.start_date, end_date: data.value.end_date, is_expected: data.value.is_expected, sort_order: data.value.sort_order, is_published: data.value.is_published } }
initialSnapshot.value = JSON.stringify(form.value); const isDirty = computed(() => JSON.stringify(form.value) !== initialSnapshot.value)
const validate = () => { errors.value = {}; const result = schema.safeParse({ ...form.value, start_date: form.value.start_date || null, end_date: form.value.end_date || null }); if (result.success) { form.value = result.data; return true } for (const issue of result.error.issues) { const key = String(issue.path[0] ?? 'form'); if (!errors.value[key]) errors.value[key] = issue.message } nextTick(() => document.getElementById(errors.value.institution ? 'institution' : errors.value.degree ? 'degree' : 'end-date')?.focus()); return false }
const save = async () => { if (!validate()) { formError.value = 'Review the highlighted fields before saving.'; return } saving.value = true; formError.value = ''; successMessage.value = ''; try { const response = await $fetch<Response>(isNew.value ? '/api/admin/education' : `/api/admin/education/${id.value}`, { method: isNew.value ? 'POST' : 'PUT', body: form.value }); form.value = { institution: response.institution, degree: response.degree, start_date: response.start_date, end_date: response.end_date, is_expected: response.is_expected, sort_order: response.sort_order, is_published: response.is_published }; initialSnapshot.value = JSON.stringify(form.value); ignoreLeavePrompt.value = true; successMessage.value = 'Education entry saved.'; if (isNew.value) await navigateTo(`/admin/education/${response.id}`, { replace: true }) } catch (error) { formError.value = error instanceof Error ? error.message : 'Unable to save this entry. Try again.' } finally { saving.value = false } }
onBeforeRouteLeave(() => { if (ignoreLeavePrompt.value || !isDirty.value || saving.value || !import.meta.client) return true; return window.confirm('You have unsaved changes. Leave without saving?') }); if (import.meta.client) { const warn = (event: BeforeUnloadEvent) => { if (!isDirty.value || saving.value) return; event.preventDefault(); event.returnValue = '' }; onMounted(() => window.addEventListener('beforeunload', warn)); onBeforeUnmount(() => window.removeEventListener('beforeunload', warn)) }
</script>
